const body = $input.first().json.body ?? $input.first().json;

const pergunta = body.pergunta ?? '';
if (!pergunta) return [];

return [{
  json: {
    pergunta,
    channel_id: body.channel_id ?? '',
    autor: body.autor ?? 'usuário'
  }
}];

const fs = require('fs');
const d = $input.first().json;

const memoriaPath = 'D:\\projetos\\Rep\\JARVIS\\JARVIS_BRAIN\\memoria\\jarvis_memoria.json';

let historico = [];
try {
  historico = JSON.parse(fs.readFileSync(memoriaPath, 'utf-8'));
  if (!Array.isArray(historico)) historico = [];
} catch(e) {
  historico = [];
}

const contexto = historico.slice(0, 3).map((entry, i) => {
  return `[Dia ${i+1} — ${entry.date}]\nResumo: ${(entry.resumo ?? []).join('; ')}\nAtenção: ${(entry.atencao ?? []).join('; ')}\nRecomendações: ${(entry.recomendacoes ?? []).join('; ')}`;
}).join('\n\n') || 'Nenhuma análise registrada ainda.';

// Passa TODOS os campos adiante incluindo channel_id e autor
return [{
  json: {
    pergunta: d.pergunta,
    channel_id: d.channel_id,
    autor: d.autor,
    contexto_memoria: contexto,
    dias_disponiveis: historico.length
  }
}];

